 29→const getScoreColor = (score: number) => {
 30→  if (score >= 70) return "bg-score-skills";
 31→  if (score >= 40) return "bg-warning";
 32→  return "bg-destructive";
 33→};
 34→
 35→const getScoreTextColor = (score: number) => {
 36→  if (score >= 70) return "text-score-skills";
 37→  if (score >= 40) return "text-warning";
 38→  return "text-destructive";
 39→};
 40→
 41→const STAGE_BADGE_CLASSES: Record<string, string> = {
 42→  applied: "border-border bg-muted/50 text-muted-foreground",
 43→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 44→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 45→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 46→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 47→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 48→};
 49→
 50→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 51→  if (score >= 70) return { label: "Strong", variant: "success" };
 52→  if (score >= 40) return { label: "Good", variant: "warning" };
 53→  return { label: "Weak", variant: "destructive" };
 54→};
 55→
 56→const getRankDisplay = (index: number) => {
 57→  if (index < 3) {
 58→    const colors = [
 59→      "bg-score-overall text-white dark:text-white",
 60→      "bg-muted-foreground/60 text-white dark:text-white",
 61→      "bg-warning text-warning-foreground",
 62→    ];
 63→    return (
 64→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 65→        {index + 1}
 66→      </span>
 67→    );
 68→  }
 69→  return (
 70→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 71→      {index + 1}
 72→    </span>
 73→  );
 74→};
 75→
 76→const CandidateRow = ({
 77→  result: r,
 78→  index,
 79→  isSelected,
 80→  isActive,
 81→  jobId,
 82→  jobTitle,
 83→  onSelect,
