 94→  return (
 95→    <>
 96→      <TableRow
 97→        className={`cursor-pointer transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
