104→        <TableCell className="text-center">
105→          {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
106→        </TableCell>
107→        <TableCell className="font-medium">
108→          <div className="flex flex-col gap-0.5">
109→            <div className="flex items-center gap-1.5 flex-wrap">
110→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
111→              {isDuplicate && (
