161→            <TooltipProvider delayDuration={300}>
162→              {r.candidate_phone && (
163→                <Tooltip>
164→                  <TooltipTrigger asChild>
165→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
166→                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
