168→                    </Button>
169→                  </TooltipTrigger>
170→                  <TooltipContent>{r.candidate_phone}</TooltipContent>
171→                </Tooltip>
172→              )}
173→              {r.candidate_email && (
174→                <Tooltip>
175→                  <TooltipTrigger asChild>
176→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
177→                      onClick={() => setEmailDialogOpen(true)}>
178→                      <Mail className="h-3.5 w-3.5" />
179→                    </Button>
180→                  </TooltipTrigger>
181→                  <TooltipContent>Email</TooltipContent>
182→                </Tooltip>
183→              )}
184→              {r.file_path && (
185→                <Tooltip>
186→                  <TooltipTrigger asChild>
187→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
188→                      onClick={() => onDownload(r.file_path!, r.filename)}>
189→                      <FileText className="h-3.5 w-3.5" />
190→                    </Button>
191→                  </TooltipTrigger>
192→                  <TooltipContent>Download</TooltipContent>
193→                </Tooltip>
194→              )}
195→              <Tooltip>
196→                <TooltipTrigger asChild>
197→                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500"
198→                    onClick={() => onDismiss(r.resume_id)}>
199→                    <Archive className="h-3.5 w-3.5" />
200→                  </Button>
201→                </TooltipTrigger>
202→                <TooltipContent>Archive</TooltipContent>
203→              </Tooltip>
204→            </TooltipProvider>
205→          </div>
206→        </TableCell>
207→      </TableRow>
208→
209→      {r.candidate_email && (
210→        <EmailOutreachDialog
211→          open={emailDialogOpen}
212→          onOpenChange={setEmailDialogOpen}
213→          candidateName={r.candidate_name || r.filename}
214→          candidateEmail={r.candidate_email}
215→          jobTitle={jobTitle || "Open Position"}
216→          matchScore={Math.round(r.overall_score ?? 0)}
217→          resumeId={r.resume_id}
218→          jobId={jobId || ""}
219→        />
220→      )}
221→    </>
222→  );
223→};
224→
225→export default CandidateRow;
