 6→const badgeVariants = cva(
 7→  "inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-xs font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
 8→  {
 9→    variants: {
10→      variant: {
11→        default: "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
12→        secondary: "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
13→        destructive: "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
14→        success: "border-transparent bg-success/15 text-success hover:bg-success/25",
15→        warning: "border-transparent bg-warning/15 text-warning hover:bg-warning/25",
16→        outline: "text-foreground",
17→      },
18→    },
19→    defaultVariants: {
20→      variant: "default",
21→    },
22→  },
23→);
24→
25→export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}
26→
27→const dotColorMap: Record<string, string> = {
28→  destructive: "bg-destructive",
29→  success: "bg-success",
30→  warning: "bg-warning",
31→};
32→
33→function Badge({ className, variant, children, ...props }: BadgeProps) {
34→  const dot = variant && dotColorMap[variant];
35→  return (
36→    <div className={cn(badgeVariants({ variant }), className)} {...props}>
37→      {dot && <span className={cn("inline-block h-1.5 w-1.5 rounded-full", dot)} />}
38→      {children}
39→    </div>
40→  );
41→}
42→
43→export { Badge, badgeVariants };
